INSERT INTO "unit_abilities" VALUES(1114000800,1007102,'优势：机动战士高达 马沙之反击 LV2','[{"tid": 100710200, "trait_id": 100710201, "trait": {"id": 100710201, "trait_type": 7, "trait_value": 20, "desc": "发起对战的敌方包含「机动战士高达 马沙之反击」系列时，\n自身攻击力及防御力提升20%", "action_timing": 0, "tlimit": 0, "active_condition_set_id": 1000261, "target_condition_set_id": 1000001, "value_source_condition_set_id": 0, "target_weapon_condition_id": 0, "use_battle_animation": false, "battle_power_value_rate_percent": 10, "trait_boost_condition_set_id": 0, "active_condition": {"id": 1000261, "trait_condition_set_id": 1000261, "group_id": "キラー_CCA攻撃", "target": "AttackTarget", "unit_tags": "", "unit_role": "", "unit_series": "1100", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": {"id": 1100, "world_id": 1, "name": "机动战士高达 马沙之反击", "desc": "由SUNRISE企划、制作，并由《机动战士高达》原作者富野由悠季老师担任总监，于1988年3月12日上映的剧场版动画作品，描写两位宿敌阿宝‧尼尔与马沙‧阿兹纳布间因缘匪浅的最后一战。\n此外，除德间书店于1987年12月推出小说版《机动战士高达 马沙之反击》外，同时角川书店也于1988年2月20日推出小说版《机动战士高达 马沙之反击 贝托蒂嘉的子嗣》。", "icon": "series_1100", "sort": 310, "schedule_id": 0, "scenario_stage_series_id": 1100, "scenario": null, "scenarios": null, "scenario_stages": null}, "character_series": null, "character_tags": null}, "target_condition": {"id": 1000001, "trait_condition_set_id": 1000001, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_a