INSERT INTO "unit_abilities" VALUES(1200005600,1009002,'优势：机动武斗传G高达 LV2','[{"tid": 100900200, "trait_id": 100900201, "trait": {"id": 100900201, "trait_type": 7, "trait_value": 20, "desc": "发起对战的敌方包含「机动武斗传G高达」系列时，\n自身攻击力及防御力提升20%", "action_timing": 0, "tlimit": 0, "active_condition_set_id": 1000310, "target_condition_set_id": 1000001, "value_source_condition_set_id": 0, "target_weapon_condition_id": 0, "use_battle_animation": false, "battle_power_value_rate_percent": 20, "trait_boost_condition_set_id": 0, "active_condition": {"id": 1000310, "trait_condition_set_id": 1000310, "group_id": "キラー_机动武闘伝Gガンダム攻撃", "target": "AttackTarget", "unit_tags": "", "unit_role": "", "unit_series": "2000", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": {"id": 2000, "world_id": 0, "name": "机动武斗传G高达", "desc": "不介意的话，请由我为各位解说G高达……\n这是60年前的事。\n人类抛弃了污染到极限的地球，将生活转移到了宇宙。\n而到了宇宙的人们，为了避免殖民地国家之间的全面战争，创造了名为「高达武斗会」这充满运动家精神的战争。\n时间来到未来世纪60年……\n「第13届高达武斗会」即将要展开了。\n但这次的大赛状况有点不同，到底会吹起什么样的武斗风暴呢……！\n那个请各位跟我一起喊！\nGundam Fight！Ready……Go——！！", "icon": "series_2000", "sort": 400, "schedule_id": 0, "scenario_stage_series_id": 2000, "scenario": null, "scenarios": null, "scenario_stages": null}, "character_series": null, "character_tags": null}, "target_condition": {"id": 1000001, "trait_condition_set_id": 1000001, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "",