INSERT INTO "unit_abilities" VALUES(1379000100,1013702,'优势：机动战士高达00 LV2','[{"tid": 101370200, "trait_id": 101370201, "trait": {"id": 101370201, "trait_type": 7, "trait_value": 20, "desc": "发起对战的敌方包含「机动战士高达00」系列时，\n自身攻击力及防御力提升20%", "action_timing": 0, "tlimit": 0, "active_condition_set_id": 1000490, "target_condition_set_id": 1000001, "value_source_condition_set_id": 0, "target_weapon_condition_id": 0, "use_battle_animation": false, "battle_power_value_rate_percent": 10, "trait_boost_condition_set_id": 0, "active_condition": {"id": 1000490, "trait_condition_set_id": 1000490, "group_id": "キラー_机动戦士ガンダム00攻撃", "target": "AttackTarget", "unit_tags": "", "unit_role": "", "unit_series": "3700", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": {"id": 3700, "world_id": 0, "name": "机动战士高达00", "desc": "西元2307年。\n地球化石燃料枯竭，但人类却发现新的取代能源，利用三座顶天立地的轨道电梯，发展出大规模太阳能发电系统。\n但发电系统却只让一部分的大国及同盟国受惠，分别是美利坚合众国为首的联邦，中国、俄罗斯、印度为首的人类革新联盟，以及欧洲为首的AEU。\n三大国家群为了各自的威信和繁荣，即使到24世纪依旧不放弃零和游戏。\n于是，出现了宣示对这社会「以武力根绝战争」的私设武装组织。\n操纵机动兵器高达的他们名为天人。\n现在，高达即将对所有战争进行武力介入……", "icon": "series_3700", "sort": 800, "schedule_id": 0, "scenario_stage_series_id": 3700, "scenario": null, "scenarios": null, "scenario_stages": null}, "character_series": null, "character_tags": null}, "target_condition": {"id": 1000001, "trait_condition_set_id": 1000001, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": null, "character_series": null, "character_tags": null}, "trait_boost": null, "granted_trait_set": null}}, {"tid": 101370200, "trait_id": 101370202, "trait": {"id": 101370202, "trait_type": 9, "trait_value": 20, "desc": "", "action_timing": 0, "tlimit": 0, "active_condition_set_id": 1000491, "target_condition_set_id": 1000001, "value_source_condition_set_id": 0, "target_weapon_condition_id": 0, "use_battle_animation": false, "battle_power_value_rate_percent": 10, "trait_boost_condition_set_id": 0, "active_condition": {"id": 1000492, "trait_condition_set_id": 1000491, "group_id": "キラー_机动戦士ガンダム00防御", "target": "ActiveAttacker", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": null, "character_series": null, "character_tags": null}, "target_condition": {"id": 1000001, "trait_condition_set_id": 1000