INSERT INTO "unit_abilities" VALUES(1761000100,1005402,'优势：机动战士高达ZZ LV2','[{"tid": 100540200, "trait_id": 100540201, "trait": {"id": 100540201, "trait_type": 7, "trait_value": 20, "desc": "发起对战的敌方包含「机动战士高达ZZ」系列时，\n自身攻击力及防御力提升20%", "action_timing": 0, "tlimit": 0, "active_condition_set_id": 1000220, "target_condition_set_id": 1000001, "value_source_condition_set_id": 0, "target_weapon_condition_id": 0, "use_battle_animation": false, "battle_power_value_rate_percent": 10, "trait_boost_condition_set_id": 0, "active_condition": {"id": 1000220, "trait_condition_set_id": 1000220, "group_id": "キラー_ZZ攻撃", "target": "AttackTarget", "unit_tags": "", "unit_role": "", "unit_series": "950", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": {"id": 950, "world_id": 1, "name": "机动战士高达ZZ", "desc": "由SUNRISE企划、制作，并由《机动战士高达》原作者富野由悠季老师担任总监，于1986年3月1日开始播出的电视动画作品。\n作品定位为《机动战士Z高达》之续篇，以该部作品中格利普斯战役后的时代为舞台，故事围绕著住在SIDE1的香格里拉中的少年捷度‧艾斯图展开。\n此外，讲谈社也于1986年推出以本作品为基础的小说作品。", "icon": "series_0950", "sort": 300, "schedule_id": 0, "scenario_stage_series_id": 950, "scenario": null, "scenarios": null, "scenario_stages": null}, "character_series": null, "character_tags": null}, "target_condition": {"id": 1000001, "trait_condition_set_id": 1000001, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battl